'use strict';
const $ = (s, root=document) => root.querySelector(s);
const game = $('#game');
const modalRoot = $('#modal-root');
const cardBook = {
 wall:{name:'철벽',cost:1,type:'방어',icon:'◧',text:'방어도 8 획득',block:8},ember:{name:'잔불 찌르기',cost:1,type:'공격',icon:'✦',text:'피해 5 · 화상 2 부여',damage:5,burn:2},crack:{name:'틈새 베기',cost:1,type:'공격',icon:'⌁',text:'피해 6. 화상이 있으면 추가 피해 6',damage:6,vsBurn:6},flurry:{name:'전격 연타',cost:1,type:'공격',icon:'ϟ',text:'피해 3을 두 번 줍니다',hits:2,damage:3},breath:{name:'숨 고르기',cost:0,type:'전술',icon:'⌇',text:'방어도 3 · 카드 1장 뽑기',block:3,draw:1},stance:{name:'반격 자세',cost:1,type:'방어',icon:'⛨',text:'방어도 5 · 다음 공격 피해 +3',block:5,boost:3},rush:{name:'방패 돌진',cost:2,type:'공격',icon:'◈',text:'피해 8 · 방어도 6 획득',damage:8,block:6},powder:{name:'화약 주머니',cost:2,type:'전술',icon:'☼',text:'화상 6 부여 · 취약 1 부여',burn:6,vulnerable:1},study:{name:'전술 분석',cost:0,type:'전술',icon:'⌕',text:'카드 1장 뽑기 · 기세 +1',draw:1,combo:1},guard:{name:'받아내기',cost:1,type:'방어',icon:'⟐',text:'방어도 6. 방어도가 10 이상이면 피해 4',block:6,guardHit:4},flare:{name:'폭렬탄',cost:1,type:'공격',icon:'✹',text:'피해 4 · 화상 4 부여',damage:4,burn:4},finisher:{name:'마무리 일격',cost:2,type:'공격',icon:'⚔',text:'피해 10. 기세 3 이상이면 피해 +8',damage:10,comboBonus:8}
};
const traits={iron:{name:'강철의 박동',icon:'⛨',text:'턴 종료 시 방어도 8 이상이면 적에게 피해 5',tag:'방어 연계'},cinder:{name:'잔불의 맹세',icon:'✹',text:'화상 피해가 2 증가합니다',tag:'화상 연계'},rhythm:{name:'연계의 달인',icon:'ϟ',text:'기세 3 도달 시 폭발 피해 +4',tag:'기세 연계'},tactician:{name:'전장의 직감',icon:'⌕',text:'매 턴 카드를 1장 더 뽑습니다',tag:'덱 순환'},bulwark:{name:'무너지지 않는 벽',icon:'◧',text:'전투 시작 시 방어도 3 획득',tag:'방어 연계'},blood:{name:'전투의 도취',icon:'♥',text:'적 처치 시 체력 5 회복',tag:'생존'}};
const enemies=[{name:'잿불 망령',kind:'흔들리는 불씨',hp:38,plans:[{kind:'hit',amount:7},{kind:'hit',amount:5},{kind:'charge',amount:9}]},{name:'회랑의 파수꾼',kind:'녹슨 수호자',hp:48,plans:[{kind:'hit',amount:8},{kind:'guard',amount:0},{kind:'hit',amount:6}]},{name:'핏빛 추적자',kind:'그림자 사냥개',hp:52,plans:[{kind:'hit',amount:6},{kind:'double',amount:4},{kind:'charge',amount:10}]},{name:'잿빛 군주',kind:'회랑의 주인',hp:82,plans:[{kind:'hit',amount:9},{kind:'double',amount:5},{kind:'charge',amount:13},{kind:'guard',amount:0}]}];
let state=null;
function makeRun(){state={screen:'welcome',stage:1,maxHp:60,hp:60,deck:['wall','wall','ember','crack','flurry','breath','stance','rush'],traits:[],wins:0,turn:1,energy:3,block:0,bonusNext:0,combo:0,enemy:null,hand:[],draw:[],discard:[],log:'전투를 시작하세요.',playerTurn:true,runDamage:0};render()}
function startBattle(){const base=enemies[Math.min(state.stage-1,enemies.length-1)];state.enemy={...base,hp:base.hp+Math.max(0,state.stage-1)*4,maxHp:base.hp+Math.max(0,state.stage-1)*4,burn:0,vulnerable:0,turn:0,block:0};state.screen='battle';state.turn=1;state.playerTurn=true;state.hand=[];state.discard=[];state.combo=0;state.bonusNext=0;state.block=0;state.energy=3;state.draw=shuffle([...state.deck]);if(state.traits.includes('bulwark'))state.block=3;drawCards(5+traitDraw());state.log='적의 움직임을 살피고, 방어와 효과를 연결하세요.';render()}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function traitDraw(){return state.traits.includes('tactician')?1:0}
function drawCards(n){for(let i=0;i<n;i++){if(!state.draw.length){if(!state.discard.length)break;state.draw=shuffle(state.discard);state.discard=[]}state.hand.push(state.draw.pop())}}
function setLog(s){state.log=s}
function render(){ $('#run-step').textContent=state.screen==='welcome'?'준비':state.screen==='battle'?`전투 ${state.stage} / 4`:state.screen==='reward'?'전리품':'완료';if(state.screen==='welcome')renderWelcome();else if(state.screen==='battle')renderBattle();else if(state.screen==='reward')renderReward();else renderEnding() }

function renderWelcome(){game.innerHTML=`<section class="welcome"><div class="hero-copy"><div class="eyebrow">A DECKBUILDING ROGUELIKE</div><h1>잿빛 <em>서약</em></h1><p>무너진 회랑에서 살아남아라. 방어를 쌓고, 적에게 화상을 남기고, 쌓인 기세를 한 번에 폭발시키세요. 작고 쉬운 규칙 속에 당신만의 연계가 기다립니다.</p><div class="hero-rule"></div><div class="feature-list"><span>4번의 전투</span><span>카드 선택으로 성장</span><span>한글 플레이</span></div><button class="primary-btn" id="start-run">여정 시작 <span>→</span></button></div><div class="hero-art"><div class="sigil">✧</div><div class="silhouette"><div class="hero-head"></div><div class="hero-cloak"></div></div><span class="art-caption">THE ASHEN CORRIDOR · 01</span></div></section>`;$('#start-run').onclick=startBattle}
function renderBattle(){const e=state.enemy;if(!e)return;const hpPct=Math.max(0,state.hp/state.maxHp*100),enemyPct=Math.max(0,e.hp/e.maxHp*100),intent=enemyIntent();game.innerHTML=`<section class="battle"><div class="battle-head"><div class="player-stats"><div class="stat-pill"><span class="stat-icon">♥</span><div><div class="stat-value">${state.hp} / ${state.maxHp}</div><div class="hpbar"><div class="hpfill" style="width:${hpPct}%"></div></div></div></div><div class="stat-pill"><span class="stat-icon" style="color:#9fc6e5">◧</span><span class="stat-value">${state.block}</span><span class="player-hp-label">방어</span></div>${state.combo>0?`<div class="stat-pill"><span class="stat-icon" style="color:#e4b96c">ϟ</span><span class="stat-value">${state.combo}</span><span class="player-hp-label">기세</span></div>`:''}</div><div class="enemy-label">${state.traits.length?`특성 ${state.traits.length}개 · `:''}잿빛 회랑</div></div><div class="battle-arena"><div class="enemy-info"><div class="enemy-title">${e.name}</div><div class="enemy-hp">${Math.max(0,e.hp)} / ${e.maxHp}</div><div class="enemy-bar"><i style="width:${enemyPct}%"></i></div><div class="intent">${intent.icon} ${intent.text} ${intent.amount?`<strong>${intent.amount}</strong>`:''}</div></div><div class="player-avatar"><div class="hero-head"></div><div class="hero-shape"></div><div class="hero-cloak"></div><div class="hero-sword"></div><span class="actor-name">방랑자</span></div><div class="vs-mark">VS</div><div class="enemy-avatar"><div class="enemy-orb"></div><div class="enemy-name">${e.kind}<small>어둠의 잔재</small></div></div><div class="arena-line"></div>${(e.burn||e.vulnerable)?`<div class="status-row">${e.burn?`<span class="status-token burn">✹ 화상 ${e.burn}</span>`:''}${e.vulnerable?`<span class="status-token">⌁ 취약 ${e.vulnerable}</span>`:''}</div>`:''}</div><div class="combat-log" id="combat-log">${state.log}</div><div class="battle-controls"><div class="energy"><div class="energy-orbs">${[0,1,2].map(i=>`<i class="energy-orb ${i<state.energy?'active':''}"></i>`).join('')}</div><span class="energy-label">${state.energy} / 3 기력</span></div><div class="draw-pile">뽑을 카드 <b>${state.draw.length}</b> · 버린 카드 <b>${state.discard.length}</b></div><button class="end-turn" id="end-turn" ${!state.playerTurn?'disabled':''}>턴 종료 ↗</button></div><div class="hand">${state.hand.map((key,i)=>cardHtml(key,i)).join('')}</div><div class="hand-note">카드를 눌러 사용 · 방어도는 적의 턴 후 사라집니다</div>${state.traits.length?`<div class="trait-strip">${state.traits.map(t=>`<span class="trait-chip" title="${traits[t].text}">${traits[t].icon} ${traits[t].name}</span>`).join('')}</div>`:''}</section>`;$$('.card',game).forEach(btn=>btn.onclick=()=>playCard(Number(btn.dataset.index)));$('#end-turn').onclick=endTurn}
function $$(sel,root=document){return [...root.querySelectorAll(sel)]}
function cardHtml(key,index){const c=cardBook[key];return `<button class="card cost-${c.cost}" data-index="${index}" ${!state.playerTurn||state.energy<c.cost?'disabled':''} aria-label="${c.name}: ${c.text}"><div class="card-top"><span class="card-cost">${c.cost}</span><span class="card-type">${c.type}</span></div><div class="card-art">${c.icon}</div><div class="card-title">${c.name}</div><div class="card-text">${c.text}</div><div class="card-hint">${c.cost===0?'기력 소모 없음':`기력 ${c.cost}`}</div></button>`}
function enemyIntent(){const e=state.enemy,p=e.plans[e.turn%e.plans.length];if(p.kind==='hit')return{icon:'⚔',text:'공격',amount:p.amount};if(p.kind==='double')return{icon:'ϟ',text:'연속 공격',amount:p.amount*2};if(p.kind==='charge')return{icon:'✹',text:'강타 준비',amount:p.amount};return{icon:'◧',text:'방어 태세',amount:0}}
function dealDamage(amount){if(!state.enemy||amount<=0)return 0;let dmg=amount;if(state.enemy.vulnerable>0)dmg=Math.ceil(dmg*1.5);if(state.enemy.block){const blocked=Math.min(dmg,state.enemy.block);state.enemy.block-=blocked;dmg-=blocked}state.enemy.hp-=dmg;state.runDamage+=dmg;return dmg}
function playCard(i){if(!state.playerTurn)return;const key=state.hand[i],c=cardBook[key];if(!c||state.energy<c.cost)return;state.energy-=c.cost;state.hand.splice(i,1);state.discard.push(key);let lines=[];if(c.block){state.block+=c.block;lines.push(`방어도 ${c.block}`)}if(c.damage){let bonus=state.bonusNext;state.bonusNext=0;let amount=c.damage+bonus;if(c.comboBonus&&state.combo>=3)amount+=c.comboBonus+(state.traits.includes('rhythm')?4:0);if(c.vsBurn&&state.enemy.burn>0)amount+=c.vsBurn;let total=0;for(let h=0;h<(c.hits||1);h++)total+=dealDamage(amount);lines.push(`피해 ${total}`)}if(c.burn){state.enemy.burn+=c.burn;lines.push(`화상 ${c.burn} 부여`)}if(c.vulnerable){state.enemy.vulnerable=Math.max(state.enemy.vulnerable,c.vulnerable);lines.push(`취약 ${c.vulnerable} 부여`)}if(c.boost){state.bonusNext+=c.boost;lines.push(`다음 공격 +${c.boost}`)}if(c.guardHit&&state.block>=10){const dmg=dealDamage(c.guardHit);lines.push(`벽의 반격 ${dmg}`)}if(c.draw){drawCards(c.draw);lines.push(`카드 ${c.draw}장 뽑기`)}if(c.combo){state.combo+=c.combo;lines.push(`기세 ${state.combo}`)}else if(c.damage||c.block)state.combo++;if(state.enemy.hp<=0){checkVictory();return}setLog(`<strong>${c.name}</strong> — ${lines.join(' · ')||'전술 발동'}`);render()}

function endTurn(){if(!state.playerTurn)return;state.playerTurn=false;const e=state.enemy;if(state.traits.includes('iron')&&state.block>=8){const dealt=dealDamage(5);state.log=`<strong>강철의 박동!</strong> 방어의 울림이 피해 ${dealt}로 번졌습니다.`}if(e.hp<=0){checkVictory();return}if(e.burn>0){const burnDamage=e.burn+(state.traits.includes('cinder')?2:0);e.hp-=burnDamage;state.log+=` <strong>화상 ${burnDamage}</strong> 피해.`;e.burn=Math.max(0,e.burn-2);if(e.hp<=0){checkVictory();return}}const plan=e.plans[e.turn%e.plans.length];if(plan.kind==='guard'){e.block+=8;state.log=`${e.name}이 몸을 웅크려 방어도 8을 얻었습니다.`}else{const hits=plan.kind==='double'?2:1,damage=plan.amount;let total=0;for(let h=0;h<hits;h++){const blocked=Math.min(state.block,damage);state.block-=blocked;const wound=damage-blocked;state.hp-=wound;total+=wound}state.log+=` ${e.name}의 공격! 방어 후 피해 <strong>${total}</strong>.`}e.turn++;if(state.hp<=0){state.hp=0;state.screen='ending';render();return}state.playerTurn=true;state.turn++;state.energy=3;state.block=0;state.combo=Math.max(0,state.combo-1);drawCards(5+traitDraw());render()}
function checkVictory(){if(state.enemy.hp<=0){state.enemy.hp=0;state.wins++;if(state.traits.includes('blood'))state.hp=Math.min(state.maxHp,state.hp+5);state.screen=state.stage>=4?'ending':'reward';render()}}
function pickReward(type){if(type==='skip'){state.stage++;startBattle();return}if(type.startsWith('trait:')){const t=type.slice(6);if(!state.traits.includes(t))state.traits.push(t)}else state.deck.push(type);state.stage++;startBattle()}
function rewardOptions(){const pool=Object.keys(cardBook).filter(k=>!state.deck.includes(k));const opts=shuffle(pool).slice(0,2).map(k=>({id:k,icon:cardBook[k].icon,name:cardBook[k].name,text:cardBook[k].text,tag:`${cardBook[k].type} 카드`}));const traitPool=Object.keys(traits).filter(k=>!state.traits.includes(k));const t=traitPool.length?shuffle(traitPool)[0]:null;if(t)opts.push({id:`trait:${t}`,icon:traits[t].icon,name:traits[t].name,text:traits[t].text,tag:traits[t].tag});while(opts.length<3){const k=shuffle(Object.keys(cardBook))[0];opts.push({id:k,icon:cardBook[k].icon,name:cardBook[k].name,text:cardBook[k].text,tag:`${cardBook[k].type} 카드`})}return opts.slice(0,3)}
function renderReward(){const options=rewardOptions();game.innerHTML=`<section class="reward-screen"><div class="eyebrow">VICTORY · ${state.wins} / 4</div><h2>전투의 흔적</h2><p>${state.enemy.name}을(를) 물리쳤습니다. 다음 전투를 위해 하나를 선택하세요.</p><div class="reward-cards">${options.map((o,i)=>`<button class="reward-card" data-choice="${i}"><span class="reward-icon">${o.icon}</span><h3>${o.name}</h3><p>${o.text}</p><span class="reward-tag">${o.tag}</span></button>`).join('')}</div><div class="reward-actions"><button class="secondary-btn" id="skip-reward">아무것도 선택하지 않기</button></div><div class="between-note">체력 ${state.hp} / ${state.maxHp} · 카드 ${state.deck.length}장 · 특성 ${state.traits.length}개</div>${state.traits.length?`<div class="trait-strip">${state.traits.map(t=>`<span class="trait-chip">${traits[t].icon} ${traits[t].name}</span>`).join('')}</div>`:''}</section>`;$$('.reward-card',game).forEach(b=>b.onclick=()=>pickReward(options[Number(b.dataset.choice)].id));$('#skip-reward').onclick=()=>pickReward('skip')}

