const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const game=$('#game');
const modalRoot=$('#modal-root');
const cardBook={
  strike:{name:'잔불 베기',icon:'⚔',type:'공격',cost:1,text:'적에게 피해 6을 줍니다.',hint:'기본 공격',effect(){dealDamage(6)}},
  guard:{name:'낡은 방패',icon:'⬟',type:'방어',cost:1,text:'방어도 7을 얻습니다.',hint:'다음 공격을 막는다',effect(){gainBlock(7)}},
  heavy:{name:'무거운 일격',icon:'✦',type:'공격',cost:2,text:'적에게 피해 13을 줍니다.',hint:'큰 한 방',effect(){dealDamage(13)}},
  feint:{name:'흐린 발놀림',icon:'〰',type:'방어',cost:0,text:'방어도 3을 얻습니다.',hint:'0 에너지',effect(){gainBlock(3)}},
  burn:{name:'불씨 새기기',icon:'♨',type:'효과',cost:1,text:'적에게 화상 4를 부여합니다.',hint:'턴 종료 시 피해',effect(){state.enemy.burn+=4}},
  riposte:{name:'반격의 자세',icon:'⤴',type:'방어',cost:1,text:'방어도 5를 얻고, 다음 공격에 피해 4를 더합니다.',hint:'방어 + 강화',effect(){gainBlock(5);state.power+=4}},
  combo:{name:'연속 베기',icon:'⚔',type:'공격',cost:1,text:'피해 4. 이번 턴 다른 카드를 냈다면 피해 5 추가.',hint:'연계 카드',effect(){dealDamage(4+(state.combo>0?5:0))}},
  mend:{name:'숨 고르기',icon:'✧',type:'효과',cost:1,text:'체력을 5 회복합니다.',hint:'최대 체력까지',effect(){state.hp=Math.min(state.maxHp,state.hp+5)}},
  pierce:{name:'틈새 찌르기',icon:'➶',type:'공격',cost:1,text:'적에게 피해 8을 줍니다. 방어 중에도 온전히 적중.',hint:'관통',effect(){dealDamage(8,true)}},
  shieldbash:{name:'방패 밀치기',icon:'⬟',type:'공격',cost:1,text:'현재 방어도만큼 피해를 주고 방어도 4를 얻습니다.',hint:'방어와 공격의 연계',effect(){dealDamage(Math.max(4,state.block));gainBlock(4)}},
  focus:{name:'전투 호흡',icon:'◎',type:'효과',cost:0,text:'이번 턴 다음 카드의 피해가 5 증가합니다.',hint:'다음 공격 강화',effect(){state.power+=5}},
  drain:{name:'핏빛 맹세',icon:'♥',type:'공격',cost:2,text:'피해 10. 적에게 준 피해의 절반만큼 회복합니다.',hint:'흡혈',effect(){const dealt=dealDamage(10);state.hp=Math.min(state.maxHp,state.hp+Math.floor(dealt/2))}}
};
const traits={
  iron:{name:'강철의 박동',icon:'⚙',tag:'방어 특성',text:'턴을 마칠 때 방어도 8 이상이면 적에게 피해 5를 줍니다.'},
  cinder:{name:'꺼지지 않는 불씨',icon:'♨',tag:'화상 특성',text:'화상이 턴 종료 시 추가로 피해 2를 줍니다.'},
  blood:{name:'붉은 서약',icon:'♥',tag:'회복 특성',text:'전투에서 승리할 때 체력을 5 회복합니다.'},
  scout:{name:'회랑의 기억',icon:'◇',tag:'전술 특성',text:'매 턴 시작 시 카드를 1장 더 뽑습니다.'}
};
const enemies=[
 {name:'회랑의 망령',title:'잊힌 수문장',hp:38,plans:[{kind:'attack',amount:7},{kind:'guard'},{kind:'attack',amount:9}]},
 {name:'재의 사냥개',title:'검은 발톱',hp:48,plans:[{kind:'double',amount:5},{kind:'attack',amount:9},{kind:'guard'}]},
 {name:'유리 수도사',title:'깨진 종의 수호자',hp:57,plans:[{kind:'attack',amount:10},{kind:'guard'},{kind:'double',amount:6}]},
 {name:'잿빛 군주',title:'회랑의 주인',hp:72,plans:[{kind:'attack',amount:12},{kind:'double',amount:7},{kind:'guard'}]}
];
let state=null;
function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function makeRun(){state={screen:'home',hp:60,maxHp:60,stage:1,wins:0,deck:['strike','strike','strike','strike','guard','guard','guard','guard','feint','burn'],draw:[],discard:[],hand:[],traits:[],energy:3,block:0,power:0,combo:0,turn:1,playerTurn:true,enemy:null,log:'',};render()}
function startBattle(){const template=enemies[state.stage-1];state.enemy={...template,hp:template.hp,maxHp:template.hp,burn:0,turn:0,block:0};state.draw=shuffle(state.deck);state.discard=[];state.hand=[];state.energy=3;state.block=0;state.power=0;state.combo=0;state.turn=1;state.playerTurn=true;state.log=`${state.enemy.name}이(가) 길을 막아섰습니다.`;drawCards(5+traitDraw());state.screen='battle';render()}
function traitDraw(){return state.traits.includes('scout')?1:0}
function drawCards(amount){for(let i=0;i<amount;i++){if(!state.draw.length){if(!state.discard.length)break;state.draw=shuffle(state.discard);state.discard=[]}state.hand.push(state.draw.pop())}}
function dealDamage(amount,piercing=false){let damage=amount+state.power;state.power=0;if(!piercing){const absorbed=Math.min(state.enemy.block,damage);state.enemy.block-=absorbed;damage-=absorbed}const dealt=Math.min(state.enemy.hp,damage);state.enemy.hp-=dealt;return dealt}
function gainBlock(amount){state.block+=amount}
function playCard(index){if(!state.playerTurn)return;const id=state.hand[index],card=cardBook[id];if(!card||card.cost>state.energy)return;state.energy-=card.cost;state.hand.splice(index,1);state.combo++;card.effect();state.discard.push(id);if(state.enemy.hp<=0){checkVictory();return}state.log=`<strong>${card.name}</strong> — ${card.text}`;render()}

function renderHome(){game.innerHTML=`<section class="welcome"><div class="hero-copy"><div class="eyebrow">A SMALL DECKBUILDING ROGUELIKE</div><h1>잿빛 <em>서약</em></h1><p>무너진 회랑을 지나 네 번의 전투를 돌파하세요. 카드를 엮고, 방어를 반격으로 바꾸며, 당신만의 서약을 완성하세요.</p><div class="hero-rule"></div><div class="feature-list"><span>4번의 전투</span><span>카드 보상</span><span>영구 특성</span></div><button class="primary-btn" id="start-run">여정 시작 <span>→</span></button></div><div class="hero-art"><div class="sigil">✦</div><div class="silhouette"></div><span class="art-caption">THE ASHEN CORRIDOR · 01</span></div></section>`;$('#start-run').onclick=()=>{state.screen='battle';startBattle()}}
function enemyPlan(){const p=state.enemy.plans[state.enemy.turn%state.enemy.plans.length];if(p.kind==='guard')return '적의 의도 · 방어도 8';if(p.kind==='double')return `적의 의도 · ${p.amount} 피해 × 2`;return `적의 의도 · ${p.amount} 피해`}
function renderBattle(){const e=state.enemy;const hpPct=Math.max(0,state.hp/state.maxHp*100),enemyPct=Math.max(0,e.hp/e.maxHp*100);const cards=state.hand.map((id,i)=>{const c=cardBook[id];return `<button class="card cost-${c.cost}" data-card="${i}" ${!state.playerTurn||state.energy<c.cost?'disabled':''} aria-label="${c.name}, 비용 ${c.cost}"><div class="card-top"><span class="card-cost">${c.cost}</span><span class="card-type">${c.type}</span></div><div class="card-art">${c.icon}</div><div class="card-title">${c.name}</div><div class="card-text">${c.text}</div><div class="card-hint">${c.hint}</div></button>`}).join('');const tokens=[];if(state.block)tokens.push(`<span class="status-token">⬟ 방어 ${state.block}</span>`);if(e.burn)tokens.push(`<span class="status-token burn">♨ 화상 ${e.burn}</span>`);if(e.block)tokens.push(`<span class="status-token">⬟ 적 방어 ${e.block}</span>`);game.innerHTML=`<section class="battle"><div class="battle-head"><div><div class="eyebrow">CHAPTER 01 · BATTLE ${state.stage} / 4</div><div class="player-stats"><div class="stat-pill"><span class="stat-icon">♥</span><div><div class="stat-value">${state.hp} / ${state.maxHp}</div><div class="hpbar"><div class="hpfill" style="width:${hpPct}%"></div></div></div></div><div class="stat-pill"><span class="stat-icon">⚔</span><span class="stat-value">턴 ${state.turn}</span></div></div></div><div class="enemy-label">잿빛 회랑<br><span class="run-step">${state.wins} 승리</span></div></div><div class="battle-arena"><div class="arena-line"></div><div class="player-avatar"><div class="hero-shape"></div><div class="hero-head"></div><div class="hero-cloak"></div><div class="hero-sword"></div><div class="actor-name">방랑자</div></div><div class="vs-mark">VS</div><div class="enemy-avatar"><div class="enemy-orb"></div><div class="enemy-name">${e.name}<small>${e.title}</small></div></div><div class="enemy-info"><div class="enemy-title">${e.name}</div><div class="enemy-hp">${e.hp} / ${e.maxHp}</div><div class="enemy-bar"><i style="width:${enemyPct}%"></i></div><div class="intent">${enemyPlan()}</div></div><div class="status-row">${tokens.join('')}</div></div><div class="combat-log">${state.log||'카드를 내어 전투를 이어가세요.'}</div><div class="battle-controls"><div class="energy"><div class="energy-orbs">${[0,1,2].map(i=>`<i class="energy-orb ${i<state.energy?'active':''}"></i>`).join('')}</div><span class="energy-label">${state.energy} / 3 에너지</span></div><div class="draw-pile">뽑을 카드 <b>${state.draw.length}</b> · 버린 카드 <b>${state.discard.length}</b></div><button class="end-turn" id="end-turn" ${!state.playerTurn?'disabled':''}>턴 종료 ↗</button></div><div class="hand">${cards||'<div class="hand-note">손에 카드가 없습니다</div>'}</div><div class="hand-note">카드를 눌러 사용 · 방어도는 적의 다음 공격까지 유지됩니다</div>${state.traits.length?`<div class="trait-strip">${state.traits.map(t=>`<span class="trait-chip">${traits[t].icon} ${traits[t].name}</span>`).join('')}</div>`:''}</section>`;$$('.card',game).forEach(b=>b.onclick=()=>playCard(Number(b.dataset.card)));$('#end-turn').onclick=endTurn}
function render(){const step=$('#run-step');if(step)step.textContent=state.screen==='home'?'준비':state.screen==='battle'?`전투 ${state.stage} / 4`:state.screen==='reward'?'전리품':'여정 종료';if(state.screen==='home')renderHome();else if(state.screen==='battle')renderBattle();else if(state.screen==='reward')renderReward();else renderEnding()}

function endTurn(){if(!state.playerTurn)return;state.playerTurn=false;const e=state.enemy;if(state.traits.includes('iron')&&state.block>=8){const dealt=dealDamage(5);state.log=`<strong>강철의 박동!</strong> 방어의 울림이 피해 ${dealt}로 번졌습니다.`}if(e.hp<=0){checkVictory();return}if(e.burn>0){const burnDamage=e.burn+(state.traits.includes('cinder')?2:0);e.hp-=burnDamage;state.log+=` <strong>화상 ${burnDamage}</strong> 피해.`;e.burn=Math.max(0,e.burn-2);if(e.hp<=0){checkVictory();return}}const plan=e.plans[e.turn%e.plans.length];if(plan.kind==='guard'){e.block+=8;state.log=`${e.name}이 몸을 웅크려 방어도 8을 얻었습니다.`}else{const hits=plan.kind==='double'?2:1,damage=plan.amount;let total=0;for(let h=0;h<hits;h++){const blocked=Math.min(state.block,damage);state.block-=blocked;const wound=damage-blocked;state.hp-=wound;total+=wound}state.log+=` ${e.name}의 공격! 방어 후 피해 <strong>${total}</strong>.`}e.turn++;if(state.hp<=0){state.hp=0;state.screen='ending';render();return}state.playerTurn=true;state.turn++;state.energy=3;state.block=0;state.power=0;state.combo=0;drawCards(5+traitDraw());render()}
function checkVictory(){if(state.enemy.hp<=0){state.enemy.hp=0;state.wins++;if(state.traits.includes('blood'))state.hp=Math.min(state.maxHp,state.hp+5);state.screen=state.stage>=4?'ending':'reward';render()}}
function pickReward(type){if(type==='skip'){state.stage++;startBattle();return}if(type.startsWith('trait:')){const t=type.slice(6);if(!state.traits.includes(t))state.traits.push(t)}else state.deck.push(type);state.stage++;startBattle()}
function rewardOptions(){const pool=Object.keys(cardBook).filter(k=>!state.deck.includes(k));const opts=shuffle(pool).slice(0,2).map(k=>({id:k,icon:cardBook[k].icon,name:cardBook[k].name,text:cardBook[k].text,tag:`${cardBook[k].type} 카드`}));const traitPool=Object.keys(traits).filter(k=>!state.traits.includes(k));const t=traitPool.length?shuffle(traitPool)[0]:null;if(t)opts.push({id:`trait:${t}`,icon:traits[t].icon,name:traits[t].name,text:traits[t].text,tag:traits[t].tag});while(opts.length<3){const k=shuffle(Object.keys(cardBook))[0];opts.push({id:k,icon:cardBook[k].icon,name:cardBook[k].name,text:cardBook[k].text,tag:`${cardBook[k].type} 카드`})}return opts.slice(0,3)}
function renderReward(){const options=rewardOptions();game.innerHTML=`<section class="reward-screen"><div class="eyebrow">VICTORY · ${state.wins} / 4</div><h2>전투의 흔적</h2><p>${state.enemy.name}을(를) 물리쳤습니다. 다음 전투를 위해 하나를 선택하세요.</p><div class="reward-cards">${options.map((o,i)=>`<button class="reward-card" data-choice="${i}"><span class="reward-icon">${o.icon}</span><h3>${o.name}</h3><p>${o.text}</p><span class="reward-tag">${o.tag}</span></button>`).join('')}</div><div class="reward-actions"><button class="secondary-btn" id="skip-reward">아무것도 선택하지 않기</button></div><div class="between-note">체력 ${state.hp} / ${state.maxHp} · 카드 ${state.deck.length}장 · 특성 ${state.traits.length}개</div>${state.traits.length?`<div class="trait-strip">${state.traits.map(t=>`<span class="trait-chip">${traits[t].icon} ${traits[t].name}</span>`).join('')}</div>`:''}</section>`;$$('.reward-card',game).forEach(b=>b.onclick=()=>pickReward(options[Number(b.dataset.choice)].id));$('#skip-reward').onclick=()=>pickReward('skip')}

function renderEnding(){const won=state.wins>=4;game.innerHTML=`<section class="ending"><div class="eyebrow">${won?'THE OATH IS FULFILLED':'THE JOURNEY ENDS'}</div><h2>${won?'회랑에 새벽이 들다':'잿더미에 남은 맹세'}</h2><p>${won?'잿빛 군주를 쓰러뜨렸습니다. 당신의 서약은 살아남았습니다.':'방랑자는 쓰러졌지만, 서약의 불씨는 사라지지 않습니다.'}</p><div class="ending-stats"><div class="ending-stat"><b>${state.wins} / 4</b><span>승리한 전투</span></div><div class="ending-stat"><b>${state.deck.length}</b><span>모은 카드</span></div><div class="ending-stat"><b>${state.traits.length}</b><span>새긴 특성</span></div></div>${state.traits.length?`<div class="trait-strip">${state.traits.map(t=>`<span class="trait-chip">${traits[t].icon} ${traits[t].name}</span>`).join('')}</div>`:''}<button class="primary-btn" id="again">다시 여정에 오르기 ↻</button></section>`;$('#again').onclick=makeRun}
function showHelp(){modalRoot.innerHTML=`<div class="modal-backdrop" role="presentation"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="help-title"><div class="eyebrow">FIELD NOTES · 01</div><h2 id="help-title">회랑에서 살아남기</h2><p>네 번의 전투를 거쳐 잿빛 군주를 쓰러뜨리세요. 매 전투마다 손에 든 카드와 적의 의도를 살펴 다음 수를 정합니다.</p><ul><li>턴마다 에너지 3을 얻습니다. 카드의 비용만큼 사용해 공격·방어·효과를 발동하세요.</li><li>방어도는 적의 다음 공격 피해를 먼저 막고, 내 턴이 시작될 때 사라집니다.</li><li>턴 종료 전 남은 방어도와 화상 효과를 활용하세요. 화상은 적의 턴 시작에 피해를 줍니다.</li><li>승리 후 카드 또는 특성을 하나 선택합니다. 특성은 이후 전투에도 계속 적용됩니다.</li></ul><button class="primary-btn" id="close-help">알겠습니다</button></section></div>`;const close=()=>{modalRoot.innerHTML=''};$('#close-help').onclick=close;$('.modal-backdrop',modalRoot).onclick=e=>{if(e.target===e.currentTarget)close()}}
$('#help-btn').onclick=showHelp;
makeRun();

