 iron:{name:'강철의 박동',icon:'⚙',tag:'방어 특성',text:'턴을 마칠 때 방어도 8 이상이면 적에게 피해 5를 줍니다.'},
 cinder:{name:'꺼지지 않는 불씨',icon:'♨',tag:'화상 특성',text:'화상이 턴 종료 시 추가로 피해 2를 줍니다.'},
 blood:{name:'붉은 서약',icon:'♥',tag:'회복 특성',text:'전투에서 승리할 때 체력을 5 회복합니다.'},
 scout:{name:'회랑의 기억',icon:'◇',tag:'전술 특성',text:'매 턴 시작 시 카드를 1장 더 뽑습니다.'}
};
const enemies=[
 {name:'회랑의 망령',title:'잊힌 수문장',hp:38,plans:[{kind:'attack',amount:7},{kind:'guard'},{kind:'attack',amount:9}]},
