function makeRun(){state={screen:'home',hp:60,maxHp:60,stage:1,wins:0,deck:['strike','strike','strike','strike','guard','guard','guard','guard','feint','burn'],draw:[],discard:[],hand:[],traits:[],energy:3,block:0,power:0,combo:0,turn:1,playerTurn:true,enemy:null,log:''};render()}
