function render(){const step=$('#run-step');if(step)step.textContent=state.screen==='home'?'준비':state.screen==='battle'?`전투 ${state.stage} / 4`:state.screen==='reward'?'전리품':'여정 종료';if(state.screen==='home')renderHome();else if(state.screen==='battle')renderBattle();else if(state.screen==='reward')renderReward();else renderEnding()}
function endTurn(){if(!state.playerTurn)return;state.playerTurn=false;const e=state.enemy;if(state.traits.includes('iron')&&state.block>=8){const dealt=dealDamage(5);state.log=`<strong>강철의 박동!</strong> 방어의 울림이 피해 ${dealt}로 번졌습니다.`}if(e.hp<=0){checkVictory();return}if(e.burn>0){const burnDamage=e.burn+(state.traits.includes('cinder')?2:0);e.hp-=burnDamage;state.log+=` <strong>화상 ${burnDamage}</strong> 피해.`;e.burn=Math.max(0,e.burn-2);if(e.hp<=0){checkVictory();return}}const plan=e.plans[e.turn%e.plans.length];if(plan.kind==='guard'){e.block+=8;state.log=`${e.name}이 몸을 웅크려 방어도 8을 얻었습니다.`}else{const hits=plan.kind==='double'?2:1,damage=plan.amount;let total=0;for(let h=0;h<hits;h++){const blocked=Math.min(state.block,damage);state.block-=blocked;const wound=damage-blocked;state.hp-=wound;total+=wound}state.log+=` ${e.name}의 공격! 방어 후 피해 <strong>${total}</strong>.`}e.turn++;if(state.hp<=0){state.hp=0;state.screen='ending';render();return}state.playerTurn=true;state.turn++;state.energy=3;state.block=0;state.power=0;state.combo=0;drawCards(5+traitDraw());render()}
function checkVictory(){if(state.enemy.hp<=0){state.enemy.hp=0;state.wins++;if(state.traits.includes('blood'))state.hp=Math.min(state.maxHp,state.hp+5);state.screen=state.stage>=4?'ending':'reward';render()}}
function pickReward(type){if(type==='skip'){state.stage++;startBattle();return}if(type.startsWith('trait:')){const t=type.slice(6);if(!state.traits.includes(t))state.traits.push(t)}else state.deck.push(type);state.stage++;startBattle()}
function rewardOptions(){const pool=Object.keys(cardBook).filter(k=>!state.deck.includes(k));const opts=shuffle(pool).slice(0,2).map(k=>({id:k,icon:cardBook[k].icon,name:cardBook[k].name,text:cardBook[k].text,tag:`${cardBook[k].type} 카드`}));const traitPool=Object.keys(traits).filter(k=>!state.traits.includes(k));const t=traitPool.length?shuffle(traitPool)[0]:null;if(t)opts.push({id:`trait:${t}`,icon:traits[t].icon,name:traits[t].name,text:traits[t].text,tag:traits[t].tag});while(opts.length<3){const k=shuffle(Object.keys(cardBook))[0];opts.push({id:k,icon:cardBook[k].icon,name:cardBook[k].name,text:cardBook[k].text,tag:`${cardBook[k].type} 카드`})}return opts.slice(0,3)}
function renderReward(){const options=rewardOptions();game.innerHTML=`<section class="reward-screen"><div class="eyebrow">VICTORY · ${state.wins} / 4</div><h2>전투의 흔적</h2><p>${state.enemy.name}을(를) 물리쳤습니다. 다음 전투를 위해 하나를 선택하세요.</p><div class="reward-cards">${options.map((o,i)=>`<button class="reward-card" data-choice="${i}"><span class="reward-icon">${o.icon}</span><h3>${o.name}</h3><p>${o.text}</p><span class="reward-tag">${o.tag}</span></button>`).join('')}</div><div class="reward-actions"><button class="secondary-btn" id="skip-reward">아무것도 선택하지 않기</button></div><div class="between-note">체력 ${state.hp} / ${state.maxHp} · 카드 ${state.deck.length}장 · 특성 ${state.traits.length}개</div>${state.traits.length?`<div class="trait-strip">${state.traits.map(t=>`<span class="trait-chip">${traits[t].icon} ${traits[t].name}</span>`).join('')}</div>`:''}</section>`;$$('.reward-card',game).forEach(b=>b.onclick=()=>pickReward(options[Number(b.dataset.choice)].id));$('#skip-reward').onclick=()=>pickReward('skip')}

