 function drawCards(amount){for(let i=0;i<amount;i++){if(!state.draw.length){if(!state.discard.length)break;state.draw=shuffle(state.discard);state.discard=[]}state.hand.push(state.draw.pop())}}
 function startBattle(){const template=enemies[state.stage-1];state.enemy={...template,hp:template.hp,maxHp:template.hp,burn:0,turn:0,block:0};state.draw=shuffle(state.deck);state.discard=[];state.hand=[];state.energy=3;state.block=0;state.power=0;state.combo=0;state.turn=1;state.playerTurn=true;state.log=`${state.enemy.name}이(가) 길을 막아섰습니다.`;drawCards(5+traitDraw());state.screen='battle';render()}
 function dealDamage(amount,piercing=false){let damage=amount+state.power;state.power=0;if(!piercing){const absorbed=Math.min(state.enemy.block,damage);state.enemy.block-=absorbed;damage-=absorbed}const dealt=Math.min(state.enemy.hp,damage);state.enemy.hp-=dealt;return dealt}
 function gainBlock(amount){state.block+=amount}
-function playCard(index){if(!state.playerTurn)return;const id=state.hand[index],card=cardBook[id];if(!card||card.cost>state.energy)return;state.energy-=card.cost;state.hand.splice(index,1);state.combo++;card.effect();state.discard.push(id);if(state.enemy.hp<=0){checkVictory();return}state.log=`<strong>${card.name}</strong> — ${card.text}`;render()}
+function playCard(index){if(!state.playerTurn)return;const id=state.hand[index],card=cardBook[id];if(!card||card.cost>state.energy)return;state.energy-=card.cost;state.hand.splice(index,1);card.effect();state.combo++;state.discard.push(id);if(state.enemy.hp<=0){checkVictory();return}state.log=`<strong>${card.name}</strong> — ${card.text}`;render()}
 function renderHome(){game.innerHTML=`<section class="welcome"><div class="hero-copy"><div class="eyebrow">A SMALL DECKBUILDING ROGUELIKE</div><h1>잿빛 <em>서약</em></h1><p>무너진 회랑을 지나 네 번의 전투를 돌파하세요. 카드를 엮고, 방어를 반격으로 바꾸며, 당신만의 서약을 완성하세요.</p><div class="hero-rule"></div><div class="feature-list"><span>4번의 전투</span><span>카드 보상</span><span>영구 특성</span></div><button class="primary-btn" id="start-run">여정 시작 <span>→</span></button></div><div class="hero-art"><div class="sigil">✦</div><div class="silhouette"></div><span class="art-caption">THE ASHEN CORRIDOR · 01</span></div></section>`;$('#start-run').onclick=()=>startBattle()}
 function enemyPlan(){const p=state.enemy.plans[state.enemy.turn%state.enemy.plans.length];if(p.kind==='guard')return '적의 의도 · 방어도 8';if(p.kind==='double')return `적의 의도 · ${p.amount} 피해 × 2`;return `적의 의도 · ${p.amount} 피해`}
 function renderBattle(){const e=state.enemy;const hpPct=Math.max(0,state.hp/state.maxHp*100),enemyPct=Math.max(0,e.hp/e.maxHp*100);const cards=state.hand.map((id,i)=>{const c=cardBook[id];return `<button class="card cost-${c.cost}" data-card="${i}" ${!state.playerTurn||state.energy<c.cost?'disabled':''} aria-label="${c.name}, 비용 ${c.cost}"><div class="card-top"><span class="card-cost">${c.cost}</span><span class="card-type">${c.type}</span></div><div class="card-art">${c.icon}</div><div class="card-title">${c.name}</div><div class="card-text">${c.text}</div><div class="card-hint">${c.hint}</div></button>`}).join('');const tokens=[];if(state.block)tokens.push(`<span class="status-token">⬟ 방어 ${state.block}</span>`);if(e.burn)tokens.push(`<span class="status-token burn">♨ 화상 ${e.burn}</span>`);if(e.block)tokens.push(`<span class="status-token">⬟ 적 방어 ${e.block}</span>`);game.innerHTML=`<section class="battle"><div class="battle-head"><div><div class="eyebrow">CHAPTER 01 · BATTLE ${state.stage} / 4</div><div class="player-stats"><div class="stat-pill"><span class="stat-icon">♥</span><div><div class="stat-value">${state.hp} / ${state.maxHp}</div><div class="hpbar"><div class="hpfill" style="width:${hpPct}%"></div></div></div></div><div class="stat-pill"><span class="stat-icon">⚔</span><span class="stat-value">턴 ${state.turn}</span></div></div></div><div class="enemy-label">잿빛 회랑<br><span class="run-step">${state.wins} 승리</span></div></div><div class="battle-arena"><div class="arena-line"></div><div class="player-avatar"><div class="hero-shape"></div><div class="hero-head"></div><div class="hero-cloak"></div><div class="hero-sword"></div><div class="actor-name">방랑자</div></div><div class="vs-mark">VS</div><div class="enemy-avatar"><div class="enemy-orb"></div><div class="enemy-name">${e.name}<small>${e.title}</small></div></div><div class="enemy-info"><div class="enemy-title">${e.name}</div><div class="enemy-hp">${e.hp} / ${e.maxHp}</div><div class="enemy-bar"><i style="width:${enemyPct}%"></i></div><div class="intent">${enemyPlan()}</div></div><div class="status-row">${tokens.join('')}</div></div><div class="combat-log">${state.log||'카드를 내어 전투를 이어가세요.'}</div><div class="battle-controls"><div class="energy"><div class="energy-orbs">${[0,1,2].map(i=>`<i class="energy-orb ${i<state.energy?'active':''}"></i>`).join('')}</div><span class="energy-label">${state.energy} / 3 에너지</span></div><div class="draw-pile">뽑을 카드 <b>${state.draw.length}</b> · 버린 카드 <b>${state.discard.length}</b></div><button class="end-turn" id="end-turn" ${!state.playerTurn?'disabled':''}>턴 종료 ↗</button></div><div class="hand">${cards||'<div class="hand-note">손에 카드가 없습니다</div>'}</div><div class="hand-note">카드를 눌러 사용 · 방어도는 적의 다음 공격까지 유지됩니다</div>${state.traits.length?`<div class="trait-strip">${state.traits.map(t=>`<span class="trait-chip">${traits[t].icon} ${traits[t].name}</span>`).join('')}</div>`:''}</section>`;$$('.card',game).forEach(b=>b.onclick=()=>playCard(Number(b.dataset.card)));$('#end-turn').onclick=endTurn}
 function render(){const step=$('#run-step');if(step)step.textContent=state.screen==='home'?'준비':state.screen==='battle'?`전투 ${state.stage} / 4`:state.screen==='reward'?'전리품':'여정 종료';if(state.screen==='home')renderHome();else if(state.screen==='battle')renderBattle();else if(state.screen==='reward')renderReward();else renderEnding()}

