function renderEnding(){
 const won=state.wins>=4;
 game.innerHTML=`<section class="ending"><div class="eyebrow">${won?'THE OATH IS FULFILLED':'THE CORRIDOR CLAIMS ANOTHER'}</div><h2>${won?'잿빛 회랑을 넘어':'여정의 끝'}</h2><p>${won?'네 번의 전투를 모두 돌파했습니다. 잿빛 서약은 당신의 이름을 기억할 것입니다.':`${state.wins}번의 승리 끝에 방랑자는 쓰러졌습니다. 다시 서약을 맺고 회랑에 도전하세요.`}</p><div class="ending-stats"><div class="ending-stat"><b>${state.wins} / 4</b><span>승리한 전투</span></div><div class="ending-stat"><b>${state.hp} / ${state.maxHp}</b><span>남은 체력</span></div><div class="ending-stat"><b>${state.deck.length}</b><span>모은 카드</span></div></div>${state.traits.length?`<div class="trait-strip">${state.traits.map(t=>`<span class="trait-chip">${traits[t].icon} ${traits[t].name}</span>`).join('')}</div>`:''}<button class="primary-btn" id="new-run">새 서약 시작 <span>→</span></button></section>`;
 $('#new-run').onclick=makeRun;
}
function closeHelp(){modalRoot.innerHTML=''}
function openHelp(){
 modalRoot.innerHTML=`<div class="modal-backdrop" role="presentation"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="help-title"><div class="eyebrow">FIELD NOTES · 01</div><h2 id="help-title">회랑의 생존법</h2><p>매 턴 에너지 3을 사용해 손의 카드를 내고, 턴 종료 전 적의 의도를 살피세요. 사용하지 않은 방어도는 적의 공격을 막지만 턴이 끝나면 사라집니다.</p><ul><li><strong>공격:</strong> 적의 체력을 깎습니다. 관통은 적 방어를 무시합니다.</li><li><strong>연계:</strong> 전투 호흡은 다음 공격을 강화하고, 연속 베기는 앞서 낸 카드가 있을 때 강해집니다.</li><li><strong>효과:</strong> 화상은 턴 종료 시 피해를 주고, 방어 특성은 충분한 방어도를 공격으로 바꿉니다.</li><li><strong>보상:</strong> 전투 후 카드 또는 영구 특성 하나를 골라 덱을 키우세요.</li></ul><button class="primary-btn" id="close-help">알겠어요</button></section></div>`;
 $('#close-help').onclick=closeHelp;
 $('.modal-backdrop',modalRoot).onclick=event=>{if(event.target===event.currentTarget)closeHelp()};
 $('#close-help').focus();
}
$('#help-btn').onclick=openHelp;
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&modalRoot.innerHTML)closeHelp()});
